  str_role_head_image_desc_frame_1000 = "Moldura padrão de avatar. A moldura inicial de cada Navegador.",
  str_role_head_image_desc_frame_2001 = "Esse padrão antigo representa que os Caçadores Silenciosos te reconhecem. Aceite esta honra suprema do passado.",
  str_role_head_image_desc_frame_2002 = "Decore seu avatar com belos acessórios!",
  str_role_head_image_desc_frame_3001 = "Abaixo do sol escaldante, acima das ondas azuis, nossas memórias inesquecíveis permanecerão eternamente nessa praia quente e calorosa.",
  str_role_head_image_desc_frame_3002 = "Coloque em sua cabeça e se parecerá um excelente soldado de Illumina.",
  str_role_head_image_desc_frame_3003 = "Quem não precisa de ajuda para pesar os prós e os contras de algo?",
  str_role_head_image_desc_frame_3004 = "Quer ser a alma da festa? Isto é tudo que você precisa!",
  str_role_head_image_desc_frame_3005 = "Um banner dedicado aos bons alunos! Mantem!",
  str_role_head_image_desc_frame_3007 = "Faremos companhia....",
  str_role_head_image_desc_frame_3008 = "O prêmio de pesca!",
  str_role_head_image_desc_frame_3010 = "É o cheiro da primavera!",
  str_role_head_image_desc_frame_3011 = "Eu sinto que isso vai me ajudar a me tornar um grande piloto!",
  str_role_head_image_desc_frame_3012 = "Sob a cortina escarlate há uma canção de ninar escura...",
  str_role_head_image_desc_frame_3013 = "A impressionante coroa é um símbolo de honra e dignidade.",
  str_role_head_image_desc_frame_3014 = "Exclusivamente para o Grande Marechal!",
  str_role_head_image_desc_frame_3015 = "Usar isso melhorará as habilidades de hospitalidade de alguém?",
  str_role_head_image_desc_frame_3018 = "É o aniversário de 1 ano! Vista-o e vá comemorar!",
  str_role_head_image_desc_frame_3019 = "Basta colocar isso e você vai ficar todo felpudo como uma Bica!",
  str_role_head_image_desc_frame_3020 = "Não se preocupe, não está quente!",
  str_role_head_image_desc_frame_3021 = "Vista isto, o grande mágico!",
  str_role_head_image_desc_frame_3022 = "O sol está muito forte, então cuide-se e não se queime!",
  str_role_head_image_desc_frame_3023 = "Parece que a garra de um morcego está agarrando sua cabeça? A faixa de cabeça é muito apertada.",
  str_role_head_image_desc_frame_3024 = "Dizem que usar este boné ajuda a fazer rap melhor. Surpreendentemente, também melhora suas habilidades no beisebol.",
  str_role_head_image_desc_frame_3025 = "Indispensável para qualquer cantor! Mergulhe na música!",
  str_role_head_image_desc_frame_3026 = "Não é para comer, é para vestir!",
  str_role_head_image_desc_frame_3027 = "Usar isso pode realmente torná-lo tão forte quanto Jeriah? Uma coisa é certa, pelo menos vai mantê-lo a salvo do vento...",
  str_role_head_image_desc_frame_3028 = "Na verdade, é um par de óculos transparentes.",
  str_role_head_image_desc_frame_3029 = "Ah! Ele é o culpado!",
  str_role_head_image_desc_frame_3031 = "Esse mundo realmente existe? Se não, por que estou aqui?",
  str_role_head_image_frame_lock_condition_2001 = "Desb. ao concluir o Selo Antigo - estágio Cemitério Silencioso.",
