  str_role_head_image_lock_condition_role_1392 = "Obtido em um evento",
  str_role_head_image_desc_1390 = "Quando você está triste, um abraço carinhoso pode melhorar?",
  str_role_head_image_desc_1391 = "Seja meu público ou seja meu parceiro, qual a sua escolha?",
  str_role_head_image_desc_1392 = "Refresque-se do calor do verão com uma refrescante tigela de gelo raspado!",
  str_role_head_image_desc_1547 = "Observá-los assim me deixa feliz.",
  str_role_head_image_lock_condition_role_1548 = "Obtido no evento Espinheiro Ardente em Flor.",
  str_role_head_image_lock_condition_role_1549 = "Compre o Livro Especial Event: Edição Luxuosa da Fase 16 para desbloquear.",
  str_role_head_image_lock_condition_role_1550 = "Obtido do evento Contador de login do convidado.",
  str_role_head_image_desc_1548 = "Sente o impulso? Então simplesmente aproveite com abertura e confiança.",
  str_role_head_image_desc_1549 = "O perigo realmente amplifica a beleza?",
  str_role_head_image_desc_1550 = "Ideias sólidas e ação formam a base do sucesso!",
  str_role_head_image_frame_lock_condition_3041 = "Obtido no evento Espinheiro Ardente em Flor.",
  str_role_head_image_frame_lock_condition_3042 = "Compre o Livro Especial Event: Edição Luxuosa da Fase 16 para desbloquear.",
  str_role_head_image_desc_frame_3041 = "Parece fácil se picar; quem estaria disposto a usar isso...",
  str_role_head_image_desc_frame_3042 = "É isso que você quer dizer com ser um cavalheiro?",
  str_role_head_image_lock_condition_role_1393 = "Obtido em um evento",
  str_role_head_image_lock_condition_role_1394 = "Obtido em um evento",
  str_role_head_image_lock_condition_role_1395 = "Obtido em um evento",
  str_role_head_image_desc_1393 = "Eu tenho uma ótima ideia para ganhar dinheiro. Quer tentar?",
  str_role_head_image_desc_1394 = "Quer saber o que está me fazendo rir? Vá em frente, tente adivinhar!",
  str_role_head_image_desc_1395 = "Minha sobremesa favorita de verão? Bem, provavelmente é sorvete com carne seca de lagarto polvilhada por cima.",
  str_role_head_image_desc_1551 = "Não podemos ter uma conversa que não envolva relatórios de trabalho?",
  str_role_head_image_lock_condition_role_1551 = "Obtido em Uma Sinfonia no Crepúsculo.",
  str_role_head_image_desc_1396 = "Olheiras? De jeito nenhum.",
  str_role_head_image_desc_1397 = "a luz brilha sobre a Cidade do Crepúsculo, dissipando as sombras que ali persistem. May",
  str_role_head_image_lock_condition_role_1396 = "Obtido em um evento",
  str_role_head_image_lock_condition_role_1397 = "Obtido em um evento",
  str_role_head_image_lock_condition_role_3755023 = "Obtido no Despertar na Tempestade.",
  str_role_head_image_lock_condition_role_3755024 = "Obtido no Despertar na Tempestade.",
  str_role_head_image_desc_3755023 = "*choraminga*... Você gosta de mim?",
  str_role_head_image_desc_3755024 = "Dente-de-leão? Não fuja de mim!",
  str_role_head_image_frame_lock_condition_3755025 = "Obtido no Despertar na Tempestade.",
  str_role_head_image_desc_frame_3755025 = "Por menor que seja a flor branca, ela representa o amanhecer...",
  str_role_head_image_desc_1552 = "\"Chega dessa piada de picolé!\"",
  str_role_head_image_lock_condition_role_1552 = "Obtido no evento Diário de Exploração.",
  str_role_head_image_desc_1553 = "\"Com as férias se aproximando, já organizei todos os meus planos de viagem. Quer saber qual é o plano do Tweety?\"",
  str_role_head_image_lock_condition_role_1553 = "Obtido no evento Golden Autumn Login.",
  str_role_head_image_desc_1398 = "\"Oh, o céu noturno... é como uma biblioteca infinita, abrigando todos os segredos do mundo.\"",
  str_role_head_image_desc_1399 = "\"Talvez um dia, eu possa realmente dominar esse poder que o destino me concedeu com sutileza.\"",
  str_role_head_image_desc_1400 = "\"Hã?\"",
  str_role_head_image_desc_1040 = "\"Negador, Reinhardt... Seja o que for que aconteça, que cada um de nós encontre seu próprio caminho.\"",
  str_role_head_image_desc_1041 = "\"Não tenho intenção nem interesse em fazer inimigos — Eles são apenas obstáculos no meu caminho.\"",
  str_role_head_image_desc_1042 = "\"A Iluminação Iluminada pode ser qualquer pessoa—você, eu, quem quer que seja—desde que guiem os Aurorianos através dos desafios.\"",
  str_role_head_image_frame_lock_condition_3043 = "Compre o Livro de Eventos Especiais: Fase 17 Deluxe Edition para desbloquear.",
  str_role_head_image_desc_frame_3043 = "Zarya estava preocupada que o frio intenso de Northland pudesse ser demais para você, então ela te deu seu chapéu.",
  str_role_head_image_desc_1401 = "Confira minha configuração de três etapas! Sim! Por que ele teve que quicar direto na tabela?!",
  str_role_head_image_desc_1402 = "Esporte é vida! Mesmo sendo um novato, darei tudo o que tenho na mesa de pingue-pongue!",
  str_role_head_image_desc_1403 = "Quando se trata de jogos, nunca vou me deixar ficar para trás! Apenas me veja dominar esses noobs na próxima grande competição de esportes eletrônicos!",
  str_role_head_image_desc_1404 = "Você não sabia? Eu sempre tenho um desempenho magnífico no campo de tiro também!",
  str_role_head_image_lock_condition_role_3755036 = "Obtido no evento Provas Entre Ondas Douradas",
  str_role_head_image_lock_condition_role_3755037 = "Obtido no evento Provas Entre Ondas Douradas",
  str_role_head_image_desc_3755036 = "Não vou deixar nenhuma pista escapar!",
  str_role_head_image_desc_3755037 = "Pode não parecer sofisticado, mas confie em mim, tem um sabor fantástico!",
  str_role_head_image_desc_3755004 = "\"Pérolas brilham suavemente, graça da luz da manhã; Florescem em silêncio, um abraço delicado; Será que o mundo percebe, essa perseguição requintada?\"",
  str_role_head_image_lock_condition_role_3755004 = "Obtido no evento Warm Winds Sign-in",
  str_role_head_image_desc_1405 = "\"Por favor, sente-se e deixe-me dar uma olhada.\"",
  str_role_head_image_desc_1406 = "\"Vou caçar qualquer um que ousar te dever dinheiro e não pagar!\"",
  str_role_head_image_desc_1407 = "Um tesouro enterrado nas profundezas do oceano.\nResiste ao desgaste constante e à erosão da água do mar, na esperança de um dia ressurgir em terra.",
  str_role_head_image_desc_1408 = "Os Celestitas tinham algumas crenças semelhantes às do meu próprio povo. Você teria interesse em visitar Ye para uma troca cultural?",
  str_role_head_image_desc_1554 = "\"Tosse, tosse... E-Estou bem... só preciso de um pouco de descanso.\"",
  str_role_head_image_desc_1555 = "\"É por minha conta hoje!\"",
  str_role_head_image_desc_1556 = "\"Uma criação de maquinaria sem função prática. Se você achar esteticamente agradável, então vale a pena tê-la.\"",
  str_role_head_image_desc_frame_3044 = "\"Não se preocupe, não vai te machucar...\"",
  str_role_head_image_frame_lock_condition_3044 = "Compre o Livro de Eventos Especiais: Fase 18 Deluxe Edition para desbloquear.",
  str_role_head_image_lock_condition_role_1554 = "Obtido no evento Golden Idol",
  str_role_head_image_lock_condition_role_1555 = "Obtido no evento Joyous Journey",
  str_role_head_image_lock_condition_role_1556 = "Obtido do evento Berth Sign-In.",
  str_role_head_image_lock_condition_role_1557 = "Obtido no evento Visitor Sign-In.",
  str_role_head_image_lock_condition_role_1558 = "Obtido no evento Countdown Gift.",
  str_role_head_image_desc_1409 = "\"Embora isso não seja nem 1% da minha riqueza, não há motivo para dizer não a dinheiro de graça.\"",
  str_role_head_image_desc_1410 = "\"Está quase nas férias. Eu deveria relaxar um pouco.\"",
  str_role_head_image_desc_1411 = "\"São três horas. Você quer uma xícara de chá?\"",
  str_role_head_image_desc_1557 = "\"Não hesite. Surpreenda seus inimigos e vença.\"",
  str_role_head_image_desc_1558 = "\"Esta moeda da sorte é para você, que está garantido de ser abençoado com sorte no próximo ano.\"",
  str_role_head_image_desc_frame_3045 = "\"Esta cobra fumegante e enrolada eventualmente devorará tudo.\"",
  str_role_head_image_frame_lock_condition_3045 = "Compre o Livro de Eventos Especiais: Fase 19 Deluxe Edition para desbloquear.",
  str_role_head_image_lock_condition_role_1559 = "Obtido no evento Ephemeral Petals Over Ashes.",
  str_role_head_image_lock_condition_role_1560 = "Obtido no evento Navigation Sign-In.",
  str_role_head_image_desc_1559 = "\"Uma cor estranha é projetada no rosto de Hiiro, provavelmente pela cor das flores de cerejeira que floresceram cedo em um lugar distante.\"",
  str_role_head_image_desc_1560 = "\"A sabedoria me sacia, não a comida.\"",
  str_role_head_image_desc_1412 = "\"Os Aurorianos são seus próprios inimigos.\"",
  str_role_head_image_desc_frame_3046 = "A linhagem da Família Sakura tem guardado silenciosamente o Hiiro em nome do resto do clã.",
  str_role_head_image_frame_lock_condition_3046 = "Obtido no evento Ephemeral Petals Over Ashes.",
  str_role_head_image_desc_1561 = "\"Quem pode resistir à vontade de esfregar a cabeça contra um tigrezinho tão fofo com poderes tão deliciosos?\"",
  str_role_head_image_desc_1562 = "\"Este nível de picância não é nada para a Rediesel Wrench.\"",
  str_role_head_image_desc_1563 = "\"O povo de Ye gosta de pratos picantes. Embora ultra picante seja um pouco demais para Dantang, ela é uma excelente cozinheira e consegue entender a beleza deste sabor.\"",
  str_role_head_image_desc_1564 = "\"Você deve sempre comer de maneira elegante! Carleen continua lembrando a si mesma que não pode esquecer a etiqueta de jantar dos Cavaleiros de Lumo apenas por causa da estimulação em sua boca.\"",
  str_role_head_image_desc_1565 = "\"Ahhhhhhhhh! Astra picante! Essa foi a primeira coisa que o estorninho disse depois de comer o molho de pimenta.\"",
  str_role_head_image_desc_1413 = "\"Eu tenho uma longa lista de coisas que gostaria de ver - a armadura mecanizada gigante em Azurite, os shows barulhentos no deserto, as intensas lutas subterrâneas...\"\nAté mesmo uma divindade tem muitos desejos para o Ano Novo.",
  str_role_head_image_desc_1414 = "Cuidado com a besta Nian de Umbraton, um verdadeiro devorador de homens com longos chifres! Confira \"Feira do Templo Proibido\", o mais recente filme de terror de Alleywood, que chega nesta primavera!\n\"Então... qual é o meu papel novamente...?\"",
  str_role_head_image_desc_1415 = "\"Aqui está, apenas algo que eu preparei... Eu posso fazer coisas além de picolés, você sabe!\"\nA única coisa que Zarya conseguiu fazer após inúmeras falhas, com um toque extra de doçura para manifestar seus sentimentos.",
  str_role_head_image_desc_1416 = "Esperando que o reencontro de hoje traga a você um sentimento de lar e força. É o mesmo céu acima de nós, onde quer que estejamos.",
  str_role_head_image_desc_1417 = "\"Celestita recebeu um chapéu especial como presente de Ano Novo e o colocou feliz!\"",
  str_role_head_image_desc_1566 = "\"Chen'ni concede bênçãos, concedendo riqueza e prosperidade!\"\nA Donzela do Dragão, reverenciada como uma divindade do mar, pode realmente conceder felicidade ao mundo mundano? Chen'ni pode não saber, mas ela está determinada a tentar!",
  str_role_head_image_desc_1567 = "\"Meu paladar é o padrão!\"\nComo enviado de Astra, o Navigator é super experiente em degustação de alimentos, ostentando um paladar refinado.",
  str_role_head_image_desc_1568 = "\"Embora muitos expressem seu carinho por mim, acho o Navegador o mais especial. Nós realmente compartilhamos uma conexão de coração para coração!\"",
  str_role_head_image_desc_1569 = "\"Coração com a mão, sério?... Tudo bem, aceite este gesto meu e seja grato... mas não se empolgue demais!\"",
  str_role_head_image_lock_condition_role_1566 = "Obtido no evento Avanço de Fim de Ano",
  str_role_head_image_lock_condition_role_1567 = "Obtido no evento Cooking Frenzy",
  str_role_head_image_desc_frame_3047 = "\"As flores de pêssego são delicadas e graciosas, irradiando sua beleza resplandecente. E a fortuna chega, em seu abraço vibrante.\"",
  str_role_head_image_desc_frame_3048 = "\"Colete todos os Cartões de Primavera para invocar o dragão divino!\"\nNão tenho certeza se é verdade, mas essa mania de colecionar cartões tornou o Ano Novo de Longzhou muito mais divertido.",
  str_role_head_image_frame_lock_condition_3047 = "Compre o Livro de Eventos Especiais: Fase 20 Deluxe Edition para desbloquear.",
  str_role_head_image_frame_lock_condition_3048 = "Obtido do evento Spring Cards: Colete todos!",
  str_role_head_image_frame_lock_condition_3049 = "Obtido no evento Encanto da Noite Bruxa.",
  str_role_head_image_frame_lock_condition_3050 = "Obtido em um evento",
  str_role_head_image_desc_frame_3049 = "\"Minha roupa irá pegar fogo quando a poção acabar. Você seguirá o último rastro da chama até mim?\"",
  str_role_head_image_desc_frame_3050 = "\"Aqueles que são perseverantes serão recompensados com glória!\"\nObrigado pela sua orientação e proteção ao longo de mil dias de perseverança e companheirismo. Aguardamos ansiosos pelas futuras aventuras juntos.",
  str_role_head_image_lock_condition_role_1570 = "Obtido no evento Encanto da Noite Bruxa.",
  str_role_head_image_desc_1570 = "\"Você quer estar no Limbo comigo? Então segure minha mão e deixe nossas esperanças queimarem brilhantemente!\"",
  str_role_head_image_desc_1418 = "\"Navegador, obrigado por me acompanhar por mil dias sob este céu. Por favor, continue a me guiar no futuro!\"",
  str_role_head_image_desc_1419 = "\"Você também quer participar do teste especial do Mooncrown Day?\"",
  str_role_head_image_desc_1420 = "\"Navegador, por aqui!\"\nO amor tem sido seu companheiro constante nesta jornada por mil dias. Continue avançando com as bênçãos de todos!",
  str_role_head_image_desc_1421 = "\"Aproveite o momento; hoje pode ser o ponto de virada em nosso destino!\"",
  str_role_head_image_frame_lock_condition_3051 = "Compre o Livro de Eventos Especiais: Fase 21 Deluxe Edition para desbloquear.",
  str_role_head_image_desc_frame_3051 = "\"Parece meio familiar.\"",
  str_role_head_image_lock_condition_role_1571 = "Obtido no evento Navigation Sign-In.",
  str_role_head_image_desc_1571 = "\"Você se escondeu? Ainda não.\"",
  str_role_head_image_lock_condition_role_1043 = "Desbloqueia após 1.050 dias de login",
  str_role_head_image_lock_condition_role_1044 = "Desbloqueia após 1.100 dias de login",
  str_role_head_image_lock_condition_role_1045 = "Desbloqueia após 1.150 dias de login",
  str_role_head_image_lock_condition_role_1046 = "Desbloqueia após 1.200 dias de login",
  str_role_head_image_lock_condition_role_1047 = "Desbloqueia após 1.250 dias de login",
  str_role_head_image_lock_condition_role_1048 = "Desbloqueia após 1.300 dias de login",
  str_role_head_image_lock_condition_role_1049 = "Desbloqueia após 1.350 dias de login",
  str_role_head_image_desc_1043 = "\"Eu entendo como é difícil o caminho para um Navegador. Continue o bom trabalho.\"",
  str_role_head_image_desc_1044 = "\"Resistir por tanto tempo é realmente louvável. Vamos continuar treinando juntos no futuro!\"",
  str_role_head_image_desc_1045 = "\"Lembre-se sempre: não importa como o tempo muda, a verdade perdura.\"",
  str_role_head_image_desc_1046 = "\"Nas jornadas futuras, sempre vou te manter seguro.\"",
  str_role_head_image_desc_1047 = "\"Quantas vezes eu te convidei para um chá da tarde?\"",
  str_role_head_image_desc_1048 = "\"Eu compartilhei minha história com você; qual é a sua?\"",
  str_role_head_image_desc_1049 = "\"Depois de tanto tempo juntos, já somos verdadeiros irmãos!\"",
  str_role_head_image_desc_1422 = "\"Croac! Croac!! Croac!!!\"",
  str_role_head_image_desc_1423 = "\"O que eu deveria fazer... A resposta sempre esteve no meu coração?\"",
  str_role_head_image_frame_lock_condition_3052 = "Obtido no evento Gerente por um Dia",
  str_role_head_image_desc_frame_3052 = "\"A figura graciosa encanta com sua fofura adorável, enredando outra em sua teia encantadora.\"",
  str_role_head_image_desc_1424 = "\"Bocejo! Sinto tanto sono desde o momento em que troquei para este pijama.\"",
  str_role_head_image_lock_condition_role_1572 = "Obtained from the Manager for a Day event",
  str_role_head_image_desc_1572 = "\"Todos os olhos estão nela; ela é o epítome da perfeição e radiância, a ídolo suprema.\"",
  str_role_head_image_lock_condition_role_1573 = "Obtido do evento Ecos de um Sonho.",
  str_role_head_image_desc_1573 = "\"Eu dou este componente ao Pai, desejando que sua expressão esteja alinhada com a exibida na tela.\"",
  str_role_head_image_lock_condition_role_1574 = "Obtained from the Echoes of a Dream event.",
  str_role_head_image_desc_1574 = "\"Pai, por favor me informe sua localização atual.\"",
  str_role_head_image_desc_1425 = "\"Olá, Toto! O caloroso Colosso abriga todo trabalhador de coração partido.\"",
  str_role_head_image_lock_condition_role_3751577 = "Obtido no evento On-Time Delivery.",
  str_role_head_image_lock_condition_role_3751579 = "Obtido do evento Paz e Harmonia.",
  str_role_head_image_frame_lock_condition_3763046 = "Obtido do evento Paz e Harmonia.",
  str_role_head_image_frame_lock_condition_3763047 = "Compre o Livro de Eventos Especiais: Fase 22 Deluxe Edition para desbloquear.",
  str_role_head_image_desc_frame_3763046 = "\"Desejo que tudo vá do seu jeito. Desejo que você seja imparável. Desejo que você alcance tudo o que deseja. Desejo que você sempre persista. Desejo que você sempre esteja comigo para que possamos compartilhar ainda mais momentos felizes juntos!\"",
  str_role_head_image_desc_frame_3763047 = "Este estandarte totêmico, que é popular em toda a Cloud Island, é um símbolo de crescimento e coragem.",
  str_role_head_image_desc_3751430 = "\"Muito bom. Não manchei minha honra hoje.\"",
  str_role_head_image_desc_3751577 = "\"Seu olhar deve ser aguçado como o de um falcão, seus ataques devem ser tão afiados quanto suas garras, e seus movimentos devem ser tão rápidos quanto suas asas batendo.\"",
  str_role_head_image_desc_3751579 = "\"May todas as coisas neste mundo se prestam à realização de seus desejos por toda a eternidade.\"",
  str_role_head_image_lock_condition_role_3751581 = "Obtido do evento Ecos de um Sonho.",
  str_role_head_image_lock_condition_role_3751582 = "Obtido do evento Ecos de um Sonho.",
  str_role_head_image_lock_condition_role_3751580 = "Obtido do evento Daily Login.",
  str_role_head_image_desc_3751581 = "\"Oh, isso é... como se sente ao ser amado por alguém?\"",
  str_role_head_image_desc_3751582 = "\"Mais uma mordida... Sim, mais uma mordida!\"",
  str_role_head_image_desc_3751580 = "\"Sou o proprietário do Hidden Fangs em Umbraton. Bem-vindo ao mundo dos jogos!\"",
  str_role_head_image_frame_lock_condition_3763048 = "Obtido no evento Imposing Dignity.",
  str_role_head_image_frame_lock_condition_3763049 = "Compre o Livro de Eventos Especiais: Fase 23 Deluxe Edition para desbloquear.",
  str_role_head_image_desc_frame_3763048 = "\"Mas não se preocupe. Nada pode permanecer o mesmo, e enquanto algumas mudanças realmente podem nos sobrecarregar, na maioria das vezes, a mudança é emocionante.\"",
  str_role_head_image_desc_frame_3763049 = "\"É possível revelar os segredos guardados pela Caixa Preta à fraca luz de uma simples vela?\"",
  str_role_head_image_lock_condition_role_3751583 = "Obtido no evento Novo Recruta Apresentando-se para o Dever.",
  str_role_head_image_lock_condition_role_3751584 = "Obtido do evento 3-Year Anniversary Sign-In.",
  str_role_head_image_lock_condition_role_3751585 = "Obtido no evento Imposing Dignity.",
  str_role_head_image_desc_3751436 = "\"É maravilhoso ter todos vocês aqui!\"",
  str_role_head_image_desc_3751583 = "\"Você precisará ser mais forte. Mais forte que os Aurorians mais fortes do mundo.\"",
  str_role_head_image_desc_3751584 = "\"Mesmo que eu morra hoje, ainda quero ver seu verdadeiro rosto.\"",
  str_role_head_image_desc_3751585 = "\"Aproximar-se dele é perfeitamente aceitável, mas peço que se comportem com um pouco mais de dignidade. Afinal, ele está aqui a meu pedido.\"",
  str_role_head_image_desc_3751438 = "\"Os buscadores da verdade são como aqueles que perseguem estrelas distantes; eles precisam de olhos sinceros para ver a luz.\"",
  str_role_head_image_desc_3751586 = "\"Eu confesso! Eu expio! Eu... Eu sou o abençoado pela verdade.\"",
  str_role_head_image_desc_frame_3763050 = "\"May a Verdade vos abençoe, e May sua vida brilhe intensamente daqui em diante.\"",
  str_role_head_image_lock_condition_role_3751438 = "Compre o Pacote de Presente para obter.",
  str_role_head_image_lock_condition_role_3751586 = "Obtido no evento Confissão Sincera.",
  str_role_head_image_frame_lock_condition_3763050 = "Obtido no evento Anniversary Sign-In.",
  str_role_head_image_desc_3751578 = "\"Vamos, repita comigo agora—Feliz Carnaval!\"",
  str_role_head_image_lock_condition_role_3751578 = "Obtido no evento Confronto de Refresco de Verão.",
  str_role_head_image_lock_condition_role_3751575 = "Obtido no evento Adventure Log.",
  str_role_head_image_lock_condition_role_3751576 = "Obtido no evento Florescimento Cintilante do Verão.",
  str_role_head_image_lock_condition_role_3751587 = "Obtido do evento Ecos de um Sonho.",
  str_role_head_image_lock_condition_role_3751588 = "Obtido do evento Ecos de um Sonho.",
  str_role_head_image_desc_3751426 = "\"O que é isso? Que comovente...\"",
  str_role_head_image_desc_3751427 = "\"Bem vindo de volta. Como foi sua aventura? Você viu algo particularmente interessante?\"",
  str_role_head_image_desc_3751428 = "\"Ah, desculpe por deixar você ver um lado tão embaraçoso de mim. Vou me certificar de manter a compostura na próxima vez.\"",
  str_role_head_image_desc_3751575 = "\"Partindo para uma nova aventura!\"",
  str_role_head_image_desc_3751576 = "\"Passar o verão com amigos é o melhor!\"",
  str_role_head_image_desc_3751587 = "\"Já que essa teimosia pode conquistar a terra, enfrentar o mar não deve ser um problema... certo?\"",
  str_role_head_image_desc_3751588 = "\"Bip-bip, ativando o modo de navegação aquática...\"",
  str_role_head_image_desc_frame_3763051 = "\"Uma boia elegante que faz você querer abraçar o mar à primeira vista. Não perca o verão fugaz - aja rapidamente e use-a para capturar a estação!\"",
  str_role_head_image_desc_frame_3763044 = "\"Todos que se banham nesta luz sentirão seus corações se tornando mais brilhantes.\"",
  str_role_head_image_desc_frame_3763045 = "\"Vir para o Astra é a surpresa mais deliciosa deste verão!\"",
  str_role_head_image_frame_lock_condition_3763051 = "Compre o Livro de Eventos Especiais: Fase 24 Deluxe Edition para desbloquear.",
  str_role_head_image_frame_lock_condition_3763044 = "Obtido em um evento",
  str_role_head_image_frame_lock_condition_3763045 = "Obtained from the Summer's Sparkling Blossoms event.",
  str_role_head_image_lock_condition_role_3751589 = "Obtido do evento A Moment of Break.",
  str_role_head_image_desc_3751444 = "\"Olhe para os competidores, totalmente envolvidos e lutando por suas posições. Por favor, aproveite este jogo e mostre seu apoio!\"",
  str_role_head_image_desc_3751443 = "\"Gosto de água e adoro nadar. Devo entrar na competição e me divertir com todos?\"",
  str_role_head_image_desc_3751589 = "\"Eu quero ter um sonho bonito, onde não há tristeza e a felicidade dura para sempre...\"",
  str_role_head_image_desc_3751594 = "\"Asas negras cortam o céu sobre o Acheron como uma lâmina afiada.\"",
  str_role_head_image_desc_3751593 = "\"Seja para negócios ou apenas por diversão, com ouro suficiente, estou à sua disposição!\"",
  str_role_head_image_desc_3751592 = "\"O juramento milenar não será esquecido. Um símbolo de gratidão do clã Longinus, concedido apenas àqueles que completam a verdadeira jornada de um herói.\"",
  str_role_head_image_desc_3751591 = "\"Não mostre misericórdia—minha lâmina está aqui para guardar as histórias das estrelas.\"",
  str_role_head_image_lock_condition_role_3751594 = "Obtido do evento Saudações Windelion.",
  str_role_head_image_lock_condition_role_3751593 = "Obtido no evento Proposta Ambiciosa.",
  str_role_head_image_desc_frame_3763052 = "\"O ouro é ofuscante!\"",
  str_role_head_image_desc_frame_3763053 = "\"Asas negras são os guardiões de um juramento milenar.\"",
  str_role_head_image_frame_lock_condition_3763052 = "Obtido no evento Proposta Ambiciosa.",
  str_role_head_image_frame_lock_condition_3763053 = "Compre o Livro de Eventos Especiais: Fase 25 Deluxe Edition para desbloquear.",
  str_role_head_image_lock_condition_role_1777 = "Obter de eventos",
  str_role_head_image_desc_1777 = "Qual vai ser a minha nova roupa? Estou animado! Mal posso esperar para vesti-la!"
}
return config
